    const date=new Date(0);date.setUTCFullYear(year,month-1,1);date.setUTCHours(0,0,0,0);
    const offset=(date.getUTCDay()+6)%7;date.setUTCMonth(month);date.setUTCDate(0);const days=date.getUTCDate();
