      area.append(element('p',`${labels.join('、')}。已按重试策略跳过，沿用此前已确认状态。${paused?'本轮生成已停止；后续正常生成会尝试恢复同步，若需要核对正文请按顶部提示操作。':''}来源处理可在“设置与资料 → 高级 → 后台处理进度”查看原因并重试；生成准备会在下次生成时重新尝试。`));
    }
  }

  function mapContent(map,compact=false) {
