  // store, and its destinations wait for the next read.
  const PRESET_SAVED_NOT_REFRESHED = '这次更改已保存，但这条提示的去向没能刷新；请重新读取预设查看。';
  const PRESET_REQUESTED_NOT_REFRESHED = '这次更改已生效，已请酒馆保存（酒馆不回报是否保存成功），但这条提示的去向没能刷新；请重新读取预设查看。';
